text:
  }
  this._socket.upgradeToSecure();
  this._secureTransport = true;
  this._actionCapa();
};

/**
 * Init authentication depending on server capabilities and user prefs.
 */
_actionAuth = async () => {
  if (!this._nextAuthMethod) {
    this._actionDone(Cr.NS_ERROR_FAILURE);
    return;
  }

  if (this._destroyed) {
    // If connection is lost, reconnect.
    this.connect();
    return;
  }

  this._authenticating = true;

  this._currentAuthMethod = this._nextAuthMethod;
  this._nextAuthMethod =
    this._possibleAuthMethods[
      this._possibleAuthMethods.indexOf(this._currentAuthMethod) + 1
    ];
  this._logger.debug(`Current auth method: ${this._currentAuthMethod}`);
  this._nextAction = this._actionAuthResponse;

  switch (this._currentAuthMethod) {
    case "USERPASS":
      this._nextAction = this._actionAuthUserPass;
      await this._send(`USER ${this._authenticator.username}`);
      break;
    case "PLAIN":
      this._nextAction = this._actionAuthPlain;
      await this._send("AUTH PLAIN");
      break;
    case "LOGIN":
      this._nextAction = this._actionAuthLoginUser;
      await this._send("AUTH LOGIN");
      break;
    case "CRAM-MD5":
      this._nextAction = this._actionAuthCramMd5;
      await this._send("AUTH CRAM-MD5");
      break;
    case "APOP": {
      const hasher = Cc["@mozilla.org/security/hash;1"].createInstance(
        Ci.nsICryptoHash
      );
      hasher.init(hasher.MD5);
      const data =
        this._apopTimestamp +
        (await this._authenticator.getByteStringPassword());
      const digest = CommonUtils.bytesAsHex(
        CryptoUtils.digestBytes(data, hasher)
      );
      await this._send(
        `APOP ${this._authenticator.username} ${digest}`,
        true
      );
      break;
    }
    case "GSSAPI": {
      try {
        this._authenticator.initGssapiAuth("pop");
        const token = this._authenticator.getNextGssapiToken("");
        this._nextAction = res => this._actionAuthGssapi(res, token);
      } catch (e) {
        this._logger.error(e);
        this._actionError("pop3GssapiFailure");
        return;
      }
      await this._send("AUTH GSSAPI");
      break;
    }
    case "NTLM": {
      try {
        this._authenticator.initNtlmAuth(
          await this._authenticator.getPassword()
        );
        const token = this._authenticator.getNextNtlmToken("");
        this._nextAction = res => this._actionAuthNtlm(res, token);
      } catch (e) {
        this._logger.error(e);
        this._actionDone(Cr.NS_ERROR_FAILURE);
        return;
      }
      await this._send("AUTH NTLM");
      break;
    }
    case "XOAUTH2":
      this._nextAction = this._actionAuthXoauth;
      await this._send("AUTH XOAUTH2");
      break;
    default:
      this._actionDone();
  }
};

/**
 * Handle authentication response.
 *
 * @param {Pop3Response} res - Authentication response received from the server.
 */
_actionAuthResponse = res => {
  this._authenticating = false;
  if (res.success) {
    this._actionAfterAuth();
    return;
  }

  if (this._nextAuthMethod) {
    // Try the next auth method.
    this._logger.debug(
      `AUTH ${this._currentAuthMethod} failed. Trying AUTH ${this._nextAuthMethod} next`
    );
    this._actionAuth();
    return;
  }

  if (this._verifyLogon) {
    this.runningUri.errorCode = "pop3PasswordFailed";
    this._actionDone(Cr.NS_ERROR_FAILURE);
    return;
  }

  if (
    ["USERPASS", "PLAIN", "LOGIN", "CRAM-MD5", "APOP"].includes(
      this._currentAuthMethod
    )
  ) {
    this._actionError(
      "pop3PasswordFailed",
      [this._server.username],
      res.statusText
    );

    // Ask user what to do.
    const action = this._authenticator.promptAuthFailed(this._msgWindow);
    if (action == 1) {
      // Cancel button pressed.
      this._actionDone(Cr.NS_ERROR_FAILURE);
      return;
    }
    if (action == 2) {
      // 'New password' button pressed.
      this._authenticator.forgetPassword();
    }

    // Retry.
    this._nextAuthMethod = this._possibleAuthMethods[0];
    this._actionAuth();
  } else if (this._currentAuthMethod == "GSSAPI") {
    this._actionError("pop3GssapiFailure", [], res.statusText);
  } else if (this._currentAuthMethod == "XOAUTH2") {
    this._logger.error(
      `Got an error name=oAuth2Error, the server said: ${res.statusText}`
    );
    const errorMessage = lazy.messengerStrings.formatStringFromName(
      "oAuth2Error",
      [this._server.hostname]
    );

    // If there's a message window on the URI, then we should alert the user.
    // Otherwise (i.e. if the getter for `msgWindow` raised
    // `NS_ERROR_NULL_POINTER`), this is a background operation and we should
    // tell the mail session to only call the listeners but not alert.
    let silent = true;
    try {
      this.runningUri.msgWindow;
      silent = false;
    } catch (ex) {
      if (
        !(ex instanceof Ci.nsIException) ||
        ex.result != Cr.NS_ERROR_NULL_POINTER
      ) {
        throw ex;
      }
    }

    MailServices.mailSession.alertUser(errorMessage, this.runningUri, silent);
    this._actionDone(Cr.NS_ERROR_FAILURE);
  }
};

/**
 * The second step of USER/PASS auth, send the password to the server.
 *
 * @param {Pop3Response} res - Response received from the server.
 */
_actionAuthUserPass = async res => {
  if (!res.success) {
    this._actionError("pop3UsernameFailure", [], res.statusText);
    return;
  }
  this._nextAction = this._actionAuthResponse;
  await this._send(
    `PASS ${await this._authenticator.getByteStringPassword()}`,
    true
  );
};

/**
 * This is the second step of PLAIN auth. Handle response to AUTH PLAIN
 * command.
 *
 * @param {Pop3Response} res - Response received from the server.
 */
_actionAuthPlain = async res => {
  if (!res.success) {
    // Command "AUTH PLAIN" failed. If there is another auth mechanism, just
    // log the failure and try the next mechanism.
    if (this._nextAuthMethod) {
      this._logger.debug(
        `AUTH PLAIN failed. Trying AUTH ${this._nextAuthMethod} next`
      );
      this._actionAuth();
    } else {
      // There are no more auth mechanisms, produce a notification to the user
      // that we are unable to authenticate (which also gets logged).
      // FIXME: Need a new error string here indicating AUTH PLAIN command
      // failed. Currently this says sending username failed but username was
      // never sent.
      this._actionError("pop3UsernameFailure", [], res.statusText);
    }
    return;
  }
  // AUTH PLAIN command succeeded. Obtain and send the plain auth token to the
  // server.
  this._nextAction = this._actionAuthResponse;
  await this._send(await this._authenticator.getPlainToken(), true);
};

/**
 * This is the second step of LOGIN auth. Handle response to AUTH LOGIN
 * command.
 *
 * @param {Pop3Response} res - Response received from the server.
 */
_actionAuthLoginUser = async res => {
  if (!res.success) {
    // Command "AUTH LOGIN" failed. If there is another auth mechanism, just
    // log the failure and try the next mechanism.
    if (this._nextAuthMethod) {
      this._logger.debug(
        `AUTH LOGIN failed, Trying AUTH ${this._nextAuthMethod} next`
      );
      this._actionAuth();
    } else {
      // There are no more auth mechanisms, produce a notification to the user
      // that we are unable to authenticate (which also gets logged).
      // FIXME: Need new error string here indicating AUTH LOGIN command
      // failed. Currently this says sending username failed but username was
      // never sent.
      this._actionError("pop3UsernameFailure", [], res.statusText);
    }
    return;
  }
  // AUTH LOGIN command succeeded. Send the base64 username to the server.
  // Note: The res.statusText here will be base64 "Username:" and is not
  // verified.
  this._nextAction = this._actionAuthLoginPass;
  this._logger.debug("Sending username for AUTH LOGIN");
  await this._send(this._authenticator.getLoginUsernameToken(), true);
};

/**
 * This is the third step of LOGIN auth. Handle the response to send of
 * username for LOGIN.
 *
 * @param {Pop3Response} res - Response received from the server.
 */
_actionAuthLoginPass = async res => {
  if (!res.success) {
    // AUTH LOGIN username failed. If there is another auth mechanism, just
    // log the failure and try the next mechanism.
    if (this._nextAuthMethod) {
      this._logger.debug(
        `AUTH LOGIN username failed. Trying AUTH ${this._nextAuthMethod} next`
      );
      this._actionAuth();
    } else {
      // There are no more auth mechanisms, produce a notification to the user
      // that we are unable to authenticate (which also gets logged).
      this._actionError("pop3UsernameFailure", [], res.statusText);
    }
    return;
  }
  // Send of username for AUTH LOGIN succeeded. Send the base64 password to
  // the server. Note: The res.statusText here will be base64 "Password:"
  // and is not verified.
  this._nextAction = this._actionAuthResponse;
  this._logger.debug("Sending password for AUTH LOGIN");
  await this._send(
    this._authenticator.getLoginPasswordToken(
      await this._authenticator.getPassword()
    ),
    true
  );
};

